function baseBarOption(chart_option, chart) {
  // 处理shape attr
  var customAttr = {};

  if (chart.customAttr) {
    customAttr = JSON.parse(chart.customAttr);

    if (customAttr.color) {
      chart_option.color = customAttr.color.colors;
    } // tooltip


    if (customAttr.tooltip) {
      var tooltip = JSON.parse(JSON.stringify(customAttr.tooltip));
      var reg = new RegExp('\n', 'g');
      tooltip.formatter = tooltip.formatter.replace(reg, '<br/>');
      chart_option.tooltip = tooltip;
    }
  } // 处理data


  if (chart.data) {
    chart_option.title.text = chart.title;
    chart_option.xAxis.data = chart.data.x;

    for (var i = 0; i < chart.data.series.length; i++) {
      var y = chart.data.series[i]; // color

      y.itemStyle = {
        color: Object(util["a" /* hexColorToRGBA */])(customAttr.color.colors[i % 9], customAttr.color.alpha)
      }; // size

      if (customAttr.size) {
        if (customAttr.size.barDefault) {
          y.barWidth = null;
          y.barGap = null;
        } else {
          y.barWidth = customAttr.size.barWidth;
          y.barGap = customAttr.size.barGap;
        }
      } // label


      if (customAttr.label) {
        y.label = customAttr.label;
      }

      y.type = 'bar';
      chart_option.legend.data.push(y.name);
      chart_option.series.push(y);
    }
  } // console.log(chart_option);


  componentStyle(chart_option, chart);
  return chart_option;
}
