function baseRadarOption(chart_option, chart) {
  // 处理shape attr
  var customAttr = {};

  if (chart.customAttr) {
    customAttr = JSON.parse(chart.customAttr);

    if (customAttr.color) {
      chart_option.color = customAttr.color.colors;
    } // size


    if (customAttr.size) {
      chart_option.radar.shape = customAttr.size.radarShape;
      chart_option.radar.radius = (customAttr.size.radarSize ? customAttr.size.radarSize : 80) + '%';
    } // tooltip


    if (customAttr.tooltip) {
      var tooltip = JSON.parse(JSON.stringify(customAttr.tooltip));
      var reg = new RegExp('\n', 'g');
      tooltip.formatter = tooltip.formatter.replace(reg, '<br/>');
      chart_option.tooltip = tooltip;
    }
  } // 处理data


  if (chart.data) {
    chart_option.title.text = chart.title;
    var maxValues = [];

    for (var i = 0; i < chart.data.series.length; i++) {
      var y = chart.data.series[i];

      if (y.data.length === 0) {
        continue;
      } // color


      y.itemStyle = {
        color: Object(util["a" /* hexColorToRGBA */])(customAttr.color.colors[i % 9], customAttr.color.alpha)
      }; // label

      if (customAttr.label) {
        y.label = customAttr.label;
      }

      chart_option.legend.data.push(y.name);
      var d = {
        name: y.name,
        type: 'radar',
        data: [{
          value: y.data,
          name: y.name,
          label: y.label
        }]
      };
      y.value = JSON.parse(JSON.stringify(y.data));
      chart_option.series.push(d);
      maxValues.push(Math.max.apply(null, y.value));
    }

    var max = Math.max.apply(null, maxValues);
    chart.data.x.forEach(function (ele) {
      chart_option.radar.indicator.push({
        name: ele,
        max: max
      });
    });
  } // console.log(chart_option);


  componentStyle(chart_option, chart);
  return chart_option;
}
