function transAxisPosition(chart, axis) {
  if (chart.type.includes('horizontal')) {
    switch (axis.position) {
      case 'top':
        return 'right';

      case 'bottom':
        return 'left';

      case 'left':
        return 'bottom';

      case 'right':
        return 'top';

      default:
        return axis.position;
    }
  } else {
    return axis.position;
  }
}
