function baseBarOptionAntV(plot, container, chart, action, isGroup, isStack) {
  // theme
  var theme = getTheme(chart); // attr

  var label = getLabel(chart);
  var tooltip = getTooltip(chart); // style

  var legend = getLegend(chart);
  var xAxis = getXAxis(chart);
  var yAxis = getYAxis(chart); // data

  var data = chart.data.datas; // options

  var options = {
    theme: theme,
    data: data,
    xField: 'field',
    yField: 'value',
    seriesField: 'category',
    appendPadding: getPadding(chart),
    label: label,
    tooltip: tooltip,
    legend: legend,
    xAxis: xAxis,
    yAxis: yAxis,
    interactions: [{
      type: 'element-active',
      cfg: {
        start: [{
          trigger: 'element:mouseenter',
          action: ['element-highlight:highlight', 'element-active:reset', 'cursor:pointer']
        }],
        end: [{
          trigger: 'element:mouseleave',
          action: ['element-highlight:reset', 'element-active:reset', 'cursor:default']
        }]
      }
    }, {
      type: 'legend-active',
      cfg: {
        start: [{
          trigger: 'legend-item:mouseenter',
          action: ['element-active:reset']
        }],
        end: [{
          trigger: 'legend-item:mouseleave',
          action: ['element-active:reset']
        }]
      }
    }, {
      type: 'legend-filter',
      cfg: {
        start: [{
          trigger: 'legend-item:click',
          action: ['list-unchecked:toggle', 'data-filter:filter', 'element-active:reset', 'element-highlight:reset']
        }]
      }
    }, {
      type: 'tooltip',
      cfg: {
        start: [{
          trigger: 'interval:mousemove',
          action: 'tooltip:show'
        }],
        end: [{
          trigger: 'interval:mouseleave',
          action: 'tooltip:hide'
        }]
      }
    }, {
      type: 'active-region',
      cfg: {
        start: [{
          trigger: 'interval:mousemove',
          action: 'active-region:show'
        }],
        end: [{
          trigger: 'interval:mouseleave',
          action: 'active-region:hide'
        }]
      }
    }]
  }; // size

  var customAttr = {};

  if (chart.customAttr) {
    customAttr = JSON.parse(chart.customAttr);

    if (customAttr.size) {
      var s = JSON.parse(JSON.stringify(customAttr.size));

      if (s.barDefault) {
        delete options.marginRatio;
      } else {
        options.marginRatio = s.barGap;
      }
    }
  } // group


  if (isGroup) {
    options.isGroup = true;
  } else {
    delete options.isGroup;
  } // stack


  if (isStack) {
    options.isStack = true;
  } else {
    delete options.isStack;
  } // 开始渲染


  if (plot) {
    plot.destroy();
  }

  plot = new external_G2Plot_["Column"](container, options);
  plot.off('interval:click');
  plot.on('interval:click', action);
  return plot;
}
