function baseTableInfo(s2, container, chart, action, tableData) {
  var containerDom = document.getElementById(container); // fields

  var fields = chart.data.fields;

  if (!fields || fields.length === 0) {
    if (s2) {
      s2.destroy();
    }

    return;
  }

  var columns = [];
  var meta = []; // add drill list

  if (chart.drill) {
    var drillFields = [];

    try {
      drillFields = JSON.parse(chart.drillFields);
    } catch (err) {
      drillFields = JSON.parse(JSON.stringify(chart.drillFields));
    }

    var drillField = drillFields[chart.drillFilters.length];
    var drillFilters = JSON.parse(JSON.stringify(chart.drillFilters));
    var drillExp = drillFilters[drillFilters.length - 1].datasetTableField; // 移除所有下钻字段

    var removeField = [];

    for (var i = 0; i < chart.drillFilters.length; i++) {
      var ele = chart.drillFilters[i].datasetTableField;
      removeField.push(ele.dataeaseName);
    } // build field


    fields.forEach(function (ele) {
      if (removeField.indexOf(ele.dataeaseName) < 0) {
        // 用下钻字段替换当前字段
        if (drillExp.dataeaseName === ele.dataeaseName) {
          columns.push(drillField.dataeaseName);
          meta.push({
            field: drillField.dataeaseName,
            name: drillField.name
          });
        } else {
          columns.push(ele.dataeaseName);
          meta.push({
            field: ele.dataeaseName,
            name: ele.name
          });
        }
      }
    });
  } else {
    fields.forEach(function (ele) {
      columns.push(ele.dataeaseName);
      meta.push({
        field: ele.dataeaseName,
        name: ele.name
      });
    });
  } // data config


  var s2DataConfig = {
    fields: {
      columns: columns
    },
    meta: meta,
    data: tableData
  }; // options

  var s2Options = {
    width: containerDom.offsetWidth,
    height: containerDom.offsetHeight,
    // showSeriesNumber: true
    style: getSize(chart)
  }; // 开始渲染

  if (s2) {
    s2.destroy();
  }

  s2 = new esm["c" /* TableSheet */](containerDom, s2DataConfig, s2Options); // click

  s2.on(esm["b" /* S2Event */].DATA_CELL_CLICK, action); // theme

  var customTheme = getCustomTheme(chart);
  s2.setThemeCfg({
    theme: customTheme
  });
  return s2;
}
